sp_widget.client_script:
api.controller = function($scope) {
    /* widget controller */
    var c = this;
	//g_form is avaiable via the page from $scope. Making it shorter here.
    var gform = $scope.page.g_form;

    $scope.setTabIndex = function(index, $event) {
        gform.setValue('current_section', index);
        $event.target.classList.remove('btn-default');
        $event.target.classList.add('btn-primary');
				//initPage(gform);
	      //gform.addErrorMessage("aaa");
				setActiveButton();
			  //setVisiable(gform,current_section)
    }
    function setActiveButton(){
		var activeTab = gform.getValue('current_section');
		$('[data-tab-index="' + activeTab + '"]').removeClass('btn-default').addClass('btn-primary');
		$('[data-tab-index]').filter(function(){
			return $(this).attr('data-tab-index') != activeTab;
		}).removeClass('btn-primary').addClass('btn-default');
	}
};

sp_widget.css:
.step-navigation-container {
  font-family: Arial, sans-serif;
  max-width: 800px;
  margin: 0 auto;
}

.step-buttons {
  display: flex;
  margin-bottom: 20px;
  border-bottom: 1px solid #ddd;
}

.btn-step {
  padding: 10px 20px;
  background: #f5f5f5;
  border: none;
  border-radius: 4px 4px 0 0;
  margin-right: 5px;
  cursor: pointer;
}

.btn-step.active {
  background: #0366d6;
  color: white;
}

.step-panel {
  padding: 20px;
  background: #f9f9f9;
  border-radius: 4px;
}
